  assert.equal(saudarCauê(), 'Olá, Cauê!');
  assert.equal(saudarCauê(), 'Olá, Cauê!');
});

test('a função original continua com this livre', () => {
  assert.equal(saudacao.call({ nome: 'Duda' }, 'Oi'), 'Oi, Duda!');
});

solutionCode:
export function saudacao(prefixo) {
  return `${prefixo}, ${this.nome}!`;
}

export function saudarComCall(nome) {
  return saudacao.call({ nome }, 'Olá');
}

export function saudarComApply(nome) {
  return saudacao.apply({ nome }, ['Olá']);
}

export function criarSaudadorFixo(nome) {
  return saudacao.bind({ nome }, 'Olá');
}
